#!/bin/bash
# A committed stock package, plus an uncommitted reservation package whose
# names break several Go conventions and a stringer-generated file whose
# underscored names are what stringer always writes.
set -euo pipefail
git init -q
git config user.name "Eval Fixture"
git config user.email "fixture@example.com"
mkdir -p stock reservation
cat > go.mod <<'GO'
module example.com/inventory

go 1.22
GO
cat > stock/stock.go <<'GO'
// Package stock tracks how many units of each item are on hand.
package stock

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// ErrUnknownItem is returned for an item the store has never stocked.
var ErrUnknownItem = errors.New("stock: unknown item")

// Store holds on-hand counts per item ID.
type Store struct {
	mu     sync.Mutex
	counts map[string]int
}

// NewStore returns an empty Store.
func NewStore() *Store { return &Store{counts: map[string]int{}} }

// Add records n more units of itemID.
func (s *Store) Add(ctx context.Context, itemID string, n int) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.counts[itemID] += n
	return nil
}

// Take removes n units of itemID, failing if fewer are on hand.
func (s *Store) Take(ctx context.Context, itemID string, n int) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	have, ok := s.counts[itemID]
	if !ok {
		return ErrUnknownItem
	}
	if have < n {
		return fmt.Errorf("stock: only %d of %s on hand", have, itemID)
	}
	s.counts[itemID] = have - n
	return nil
}
GO
git add -A
git commit -qm "Add stock store"
cat > reservation/reservation.go <<'GO'
// Package reservation holds stock for a customer's cart.
package reservation

//go:generate stringer -type=Status

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

const MAX_QUANTITY = 10

var NotFound = errors.New("Reservation not found.")

// Status says whether a reservation still holds its stock.
type Status int

const (
	Held Status = iota
	Released
)

type IStockTaker interface {
	Take(ctx context.Context, itemID string, n int) error
}

type Reservation struct {
	reservationId string
	itemId        string
	quantity      int
	status        Status
}

func (r Reservation) GetQuantity() int { return r.quantity }

func (r Reservation) Status() Status { return r.status }

type ReservationService struct {
	mu    sync.Mutex
	stock IStockTaker
	held  map[string]Reservation
}

func NewReservationService(stock IStockTaker) *ReservationService {
	return &ReservationService{stock: stock, held: map[string]Reservation{}}
}

func (self *ReservationService) Hold(ctx context.Context, reservationId, itemId string, quantity int) error {
	if quantity < 1 || quantity > MAX_QUANTITY {
		return fmt.Errorf("reservation: quantity %d out of range", quantity)
	}
	self.mu.Lock()
	defer self.mu.Unlock()
	if _, exists := self.held[reservationId]; exists {
		return fmt.Errorf("reservation: %s already held", reservationId)
	}
	if err := self.stock.Take(ctx, itemId, quantity); err != nil {
		return err
	}
	self.held[reservationId] = Reservation{reservationId: reservationId, itemId: itemId, quantity: quantity, status: Held}
	return nil
}

func (self *ReservationService) Find(reservationId string) (Reservation, error) {
	self.mu.Lock()
	defer self.mu.Unlock()
	r, ok := self.held[reservationId]
	if !ok {
		return Reservation{}, NotFound
	}
	return r, nil
}
GO
cat > reservation/status_string.go <<'GO'
// Code generated by "stringer -type=Status"; DO NOT EDIT.

package reservation

import "strconv"

func _() {
	// An "invalid array index" compiler error signifies that the constant values have changed.
	// Re-run the stringer command to generate them again.
	var x [1]struct{}
	_ = x[Held-0]
	_ = x[Released-1]
}

const _Status_name = "HeldReleased"

var _Status_index = [...]uint8{0, 4, 12}

func (i Status) String() string {
	if i < 0 || i >= Status(len(_Status_index)-1) {
		return "Status(" + strconv.FormatInt(int64(i), 10) + ")"
	}
	return _Status_name[_Status_index[i]:_Status_index[i+1]]
}
GO
